#include <queue>
#include <iostream>

int main() {
    std::queue<int> q;
    q.push(10);
    q.push(20);

    // Safe processing sequence:
    if (!q.empty()) {
        int oldest = q.front();  // Step 1: Access value
        std::cout << "Oldest: " << oldest << "\n";
        q.pop();                 // Step 2: Remove element
    }

    // Accessing newest element without removal:
    if (!q.empty()) {
        int& newest = q.back();
        newest = 30; // Modifying the element in place
    }

    // q.pop(); q.pop(); // UB if called again without check
}
